code:
public class Main {
    static boolean allPositive(int[] values) {
        for (int v : values) {
            if (v > 0) {
                return true;
            } else {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] readings = {3, 8, -2, 5};
        boolean ok = allPositive(readings);
        System.out.println("All positive: " + ok);
    }
}

fix:
public class Main {
    static boolean allPositive(int[] values) {
        for (int v : values) {
            if (v <= 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] readings = {3, 8, -2, 5};
        boolean ok = allPositive(readings);
        System.out.println("All positive: " + ok);
    }
}

