code:
public class Main {
    static int countDigits(int n) {
        int digits = 0;
        while (n > 0) {
            digits++;
            n /= 10;
        }
        return digits;
    }

    public static void main(String[] args) {
        System.out.println("4096 -> " + countDigits(4096));
        System.out.println("0 -> " + countDigits(0));
    }
}

fix:
public class Main {
    static int countDigits(int n) {
        int digits = 0;
        do {
            digits++;
            n /= 10;
        } while (n > 0);
        return digits;
    }

    public static void main(String[] args) {
        System.out.println("4096 -> " + countDigits(4096));
        System.out.println("0 -> " + countDigits(0));
    }
}

